    wrap.appendChild(el10("div", "la-settings-hint", "Replaces the icon shown in the Lumiverse sidebar."));
    const iconPreview = el10("div", "la-icon-settings-preview");
    const iconFrame = el10("div", "la-icon-settings-frame");
